--shadow-sm: 0 1px 2px rgba(0,0,0,0.40);
--shadow-md: 0 4px 12px rgba(0,0,0,0.55);
--shadow-lg: 0 12px 28px rgba(0,0,0,0.65);
--shadow-xl: 0 20px 40px rgba(0,205,60,0.40);  /* 플레이 강조 */
--duration-fast: 120ms;
--duration-base: 220ms;
--duration-slow: 360ms;
--ease-out: cubic-bezier(0.16, 1, 0.3, 1);
--ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}
:root {
  /* Primary - Melon Green (다크 대비 위해 500을 #14D050로 미세 상향) */
  --color-primary-50:  #04361A;
  --color-primary-100: #045226;
  --color-primary-200: #007A24;
  --color-primary-300: #00A832;
  --color-primary-400: #00CD3C;
  --color-primary-500: #14D050;   /* Melon Green (on-dark) */
  --color-primary-600: #3FD86A;
  --color-primary-700: #7DE498;
  --color-primary-800: #B8F0C5;
  --color-primary-900: #E6FAEB;

  /* Secondary - 액센트 핫핑크 (좋아요/하트) */
  --color-secondary-500: #FF5C84;

  /* Neutral (0=가장 밝은 텍스트 → 1000=캔버스) */
  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #F8F9FA;
  --color-neutral-100:  #E4E6E9;
  --color-neutral-200:  #BCC0C4;     /* text secondary */
  --color-neutral-300:  #8A8F94;
  --color-neutral-500:  #5F6368;
  --color-neutral-700:  #3A3C40;     /* elevated border */
  --color-neutral-800:  #2D2F33;     /* border */
  --color-neutral-900:  #1B1C1F;     /* surface subtle */
  --color-neutral-1000: #121212;     /* canvas */

  /* Semantic (dark-coherent: 깊은 배경 + 밝은 전경) */
  --color-success-bg: #0C3018;
  --color-success-fg: #38E06A;
  --color-warning-bg: #3A2A08;
  --color-warning-fg: #FFB938;
  --color-error-bg:   #3A1218;
  --color-error-fg:   #FF6B6B;
  --color-info-bg:    #0E2A4A;
  --color-info-fg:    #5AA1FF;

  /* Surface */
  --bg-base:     #121212;
  --bg-subtle:   #1B1C1F;
  --bg-elevated: #232427;
  --bg-overlay:  rgba(0,0,0,0.65);

  /* Text */
  --text-primary:    #F8F9FA;
  --text-secondary:  #D2D5D9;
  --text-tertiary:   #BCC0C4;
  --text-on-primary: #0A0A0A;
  --text-disabled:   #6B6F74;

  /* Border */
  --border-default: #2D2F33;
  --border-subtle:  #232427;
  --border-strong:  #3A3C40;
  --border-focus:   #14D050;
}

[data-theme="light"] {
  /* Primary - Melon Green (라이트 표면용 원본) */
  --color-primary-50:  #E6FAEB;
  --color-primary-100: #B8F0C5;
  --color-primary-200: #7DE498;
  --color-primary-300: #3FD86A;
  --color-primary-400: #14D050;
  --color-primary-500: #00CD3C;   /* Melon Green */
  --color-primary-600: #00B834;
  --color-primary-700: #00A832;
  --color-primary-800: #007A24;
  --color-primary-900: #004D17;

  /* Secondary - 액센트 핫핑크 (좋아요/하트) */
  --color-secondary-500: #FF3B6A;

  /* Neutral */
  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #F8F9FA;
  --color-neutral-100:  #F1F3F4;
  --color-neutral-200:  #ECEEF0;     /* border */
  --color-neutral-300:  #DADCE0;
  --color-neutral-500:  #9AA0A6;
  --color-neutral-700:  #5F6368;     /* text secondary */
  --color-neutral-800:  #3C4043;
  --color-neutral-900:  #1B1B1B;     /* text primary */
  --color-neutral-1000: #000000;

  /* Semantic */
  --color-success-bg: #E6FAEB;
  --color-success-fg: #00CD3C;
  --color-warning-bg: #FFF4D6;
  --color-warning-fg: #F29900;
  --color-error-bg:   #FFE8EC;
  --color-error-fg:   #EA4335;
  --color-info-bg:    #E8F0FE;
  --color-info-fg:    #1A73E8;

  /* Surface */
  --bg-base:     #FFFFFF;
  --bg-subtle:   #F8F9FA;
  --bg-elevated: #FFFFFF;
  --bg-overlay:  rgba(27,27,27,0.55);

  /* Text */
  --text-primary:    #1B1B1B;
  --text-secondary:  #3C4043;
  --text-tertiary:   #5F6368;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #9AA0A6;

  /* Border */
  --border-default: #ECEEF0;
  --border-subtle:  #F1F3F4;
  --border-strong:  #DADCE0;
  --border-focus:   #00CD3C;
}




.btn { font: 700 13px/1 Pretendard, sans-serif; letter-spacing: -0.01em;
       border-radius: var(--radius-md); padding: 10px 16px; border: 0;
       display: inline-flex; align-items: center; justify-content: center; gap: 6px;
       transition: background 150ms ease; }
.btn-primary { background: var(--color-primary-500); color: #0A0A0A; }
.btn-primary:hover { background: var(--color-primary-600); }
.btn-secondary { background: var(--bg-subtle); color: var(--text-primary); }
.btn-ghost { background: transparent; color: var(--color-primary-500); }
.btn-play { width: 44px; height: 44px; padding: 0; border-radius: 9999px; background: var(--color-primary-500); color: #0A0A0A; }
.btn-like { width: 36px; height: 36px; padding: 0; border-radius: 9999px; background: transparent; color: var(--color-secondary-500); }
.search-input { background: var(--bg-subtle); border: 0; border-radius: 9999px; padding: 10px 16px; font: 500 14px/1.4 inherit; }
.search-input:focus { outline: 2px solid var(--color-primary-500); }
.track-card { background: var(--bg-elevated); border: 1px solid var(--border-default); border-radius: var(--radius-lg); padding: 10px; display: grid; grid-template-columns: 44px 1fr auto; gap: 10px; align-items: center; }
.album-card { background: var(--bg-elevated); border-radius: var(--radius-md); overflow: hidden; }
.album-card .cover { aspect-ratio: 1; background: var(--bg-subtle); }
.chart-card { background: linear-gradient(135deg, var(--color-primary-500) 0%, var(--color-primary-300) 100%); color: #0A0A0A; border-radius: var(--radius-lg); padding: 16px; }
.tag { padding: 2px 6px; border-radius: 4px; font: 700 10px/1.5 inherit; }
.tag-new   { background: var(--color-primary-500); color: #0A0A0A; }
.tag-rank  { background: var(--color-secondary-500); color: #fff; }
.tag-19    { background: #FF6B6B; color: #0A0A0A; }
.tabbar { background: #1B1C1F; border-top: 1px solid var(--border-default); display: grid; grid-template-columns: repeat(5, 1fr); padding: 4px 0; }
.tabbar .item { padding: 6px; text-align: center; font: 600 11px/1.3 inherit; color: var(--text-tertiary); }
.tabbar .item.active { color: var(--color-primary-500); }
